import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int N,
    float eps)
{
    int batch = blockIdx.x;
    const float* x_b = x + (long)batch * N;
    float* out_b = out + (long)batch * N;

    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sqsum = sdata + blockDim.x;

    float sum = 0.0f;
    float sqsum = 0.0f;

    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        float v = x_b[i];
        sum += v;
        sqsum += v * v;
    }

    s_sum[threadIdx.x] = sum;
    s_sqsum[threadIdx.x] = sqsum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sqsum[threadIdx.x] += s_sqsum[threadIdx.x + stride];
        }
        __syncthreads();
    }

    __shared__ float mean;
    __shared__ float invstd;

    if (threadIdx.x == 0) {
        mean = s_sum[0] / N;
        float var = s_sqsum[0] / N - mean * mean;
        if (var < 0.0f) var = 0.0f;
        invstd = rsqrtf(var + eps);
    }
    __syncthreads();

    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        float v = x_b[i];
        out_b[i] = (v - mean) * invstd * gamma[i] + beta[i];
    }
}

torch::Tensor layernorm_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    double eps)
{
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);

    int batch_size = x_contig.size(0);
    long N = x_contig.numel() / batch_size;

    const int threads = 256;
    const int blocks = batch_size;
    const int shared_mem = 2 * threads * sizeof(float);

    layernorm_kernel<<<blocks, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)N,
        (float)eps
    );

    return out;
}
"""

layernorm_cpp_source = r"""
torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layernorm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Layer Normalization using a custom fused CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.contiguous()
        bias = self.bias.contiguous()
        return layernorm_module.layernorm_cuda(x, weight, bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256


def get_inputs():
    x = torch.rand(batch_size, features, dim1, dim2)
    return [x]


def get_init_inputs():
    return [(features, dim1, dim2)]

